7.5 Store 模式：函数式更新
AppState 使⽤函数式更新模式，类似 Redux：
// src/state/store.ts
export function createStore(initialState: AppState, onChange?) {
  let state = initialState
  return {
    getState(): AppState {
      return state
    },
    setState(updater: (prev: AppState) => AppState): void {
      const newState = updater(state)
      const oldState = state
      state = newState
