流式处理中的错误处理⽐同步代码更复杂：
async function* safeQuery(params) {
  try {
    yield* query(params)
  } catch (error) {
    if (error instanceof AbortError) {
      // 用户主动中断，正常退出
      yield { type: 'interrupted' }
    } else if (isRetryableError(error)) {
      // 可重试的错误，自动重试
      yield* safeQuery(params)
    } else {
      // 不可恢复的错误，yield 错误消息
      yield { type: 'error', error: error.message }
    }
  }
}

