async function compactConversation(
  messages: Message[],
  systemPrompt: SystemPrompt
): Promise<Message[]> {
  // 1. 找到压缩边界（保留最近的 N 条消息不压缩）
  const { toCompress, toKeep } = splitAtCompactBoundary(messages)
